{
    "name": "@cortexkit/magic-context",
    "version": "0.49.55",
    "description": "Unified CLI for Magic Context — setup, doctor, and migration across OpenCode, Pi, and OMP",
    "keywords": [
        "opencode",
        "opencode-plugin",
        "pi",
        "pi-extension",
        "omp",
        "oh-my-pi",
        "magic-context",
        "cli",
        "setup",
        "doctor"
    ],
    "author": "Cortexkit",
    "license": "MIT",
    "repository": {
        "type": "git",
        "url": "https://github.com/cortexkit/magic-context"
    },
    "homepage": "https://github.com/cortexkit/magic-context#readme",
    "bugs": {
        "url": "https://github.com/cortexkit/magic-context/issues"
    },
    "type": "module",
    "bin": {
        "magic-context": "dist/index.js"
    },
    "files": [
        "dist",
        "README.md"
    ],
    "scripts": {
        "build": "bun ../../scripts/check-bun.mjs && bun build src/index.ts --outfile dist/index.js --target node --format esm --external node:sqlite",
        "typecheck": "tsc --noEmit",
        "test": "bun ../../scripts/check-bun.mjs && bun run src/test-runner.ts",
        "lint": "bun ../../scripts/check-bun.mjs && biome check src",
        "format": "biome format --write src",
        "format:check": "biome format src",
        "prepublishOnly": "bun run build"
    },
    "dependencies": {
        "@clack/prompts": "^1.6.0",
        "@cortexkit/subc-client": "0.11.1",
        "comment-json": "^5.0.0",
        "jsonc-parser": "^3.3.1"
    },
    "devDependencies": {
        "@biomejs/biome": "^2.5.1",
        "@types/better-sqlite3": "^7.6.13",
        "@types/node": "^22.20.0",
        "typescript": "^5.8.0"
    },
    "engines": {
        "node": "^22.16.0 || >=24.0.0"
    }
}
